const express = require('express');
const session = require('express-session');
const crypto = require('node:crypto');
const { promisify } = require('node:util');

const scrypt = promisify(crypto.scrypt);

const MAX_ATTEMPTS = 5;
const WINDOW_MS = 15 * 60 * 1000;

// ponytail: in-memory users, lost on restart. Swap for a DB table when users must persist.
const users = new Map(); // username -> { hash }
// ponytail: in-memory counters, per-process. Move to Redis when running more than one instance.
const attempts = new Map(); // key -> { count, resetAt }

async function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const key = await scrypt(password, salt, 64);
  return `${salt.toString('hex')}:${key.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [salt, key] = stored.split(':').map((h) => Buffer.from(h, 'hex'));
  return crypto.timingSafeEqual(key, await scrypt(password, salt, 64));
}

// Verified against when the user doesn't exist, so response time doesn't reveal valid usernames.
const dummyHash = hashPassword(crypto.randomBytes(16).toString('hex'));

// Counts an attempt; returns seconds until retry if over the limit, else 0.
// Counted before the password check so parallel requests can't all slip under the limit.
function take(key) {
  const now = Date.now();
  let a = attempts.get(key);
  if (!a || a.resetAt <= now) attempts.set(key, (a = { count: 0, resetAt: now + WINDOW_MS }));
  a.count++;
  return a.count > MAX_ATTEMPTS ? Math.ceil((a.resetAt - now) / 1000) : 0;
}

setInterval(() => {
  const now = Date.now();
  for (const [key, a] of attempts) if (a.resetAt <= now) attempts.delete(key);
}, WINDOW_MS).unref();

function credentials(req, res) {
  const { username, password } = req.body ?? {};
  if (typeof username === 'string' && typeof password === 'string' && username && password) {
    return { username, password };
  }
  res.status(400).json({ error: 'username and password required' });
}

function requireAuth(req, res, next) {
  if (req.session.user) return next();
  res.status(401).json({ error: 'not logged in' });
}

const app = express();
// Behind a reverse proxy, set `app.set('trust proxy', 1)` or req.ip is the proxy's and everyone shares one limit.
app.use(express.json());
app.use(
  session({
    // Random fallback is safe but logs everyone out on restart; set SESSION_SECRET in production.
    secret: process.env.SESSION_SECRET ?? crypto.randomBytes(32).toString('hex'),
    resave: false,
    saveUninitialized: false,
    // ponytail: default MemoryStore leaks and is per-process. Use connect-redis or similar in production.
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: process.env.NODE_ENV === 'production',
      maxAge: 24 * 60 * 60 * 1000,
    },
  })
);

app.post('/register', async (req, res) => {
  const creds = credentials(req, res);
  if (!creds) return;
  if (creds.password.length < 8) return res.status(400).json({ error: 'password must be at least 8 characters' });
  if (users.has(creds.username)) return res.status(409).json({ error: 'username taken' });
  users.set(creds.username, { hash: await hashPassword(creds.password) });
  res.status(201).json({ username: creds.username });
});

app.post('/login', async (req, res, next) => {
  const creds = credentials(req, res);
  if (!creds) return;

  // Per-IP stops one client spraying usernames; per-username stops many IPs hammering one account.
  const keys = [`ip:${req.ip}`, `user:${creds.username}`];
  const retryAfter = Math.max(...keys.map(take));
  if (retryAfter) {
    return res.set('Retry-After', String(retryAfter)).status(429).json({ error: 'too many attempts, try again later' });
  }

  const user = users.get(creds.username);
  const ok = await verifyPassword(creds.password, user ? user.hash : await dummyHash);
  if (!user || !ok) return res.status(401).json({ error: 'invalid username or password' });

  for (const key of keys) attempts.get(key).count--; // only failures count

  // New session id on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.user = creds.username;
    res.json({ username: creds.username });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('connect.sid').status(204).end();
  });
});

app.get('/me', requireAuth, (req, res) => res.json({ username: req.session.user }));

if (require.main === module) {
  const port = process.env.PORT ?? 3000;
  app.listen(port, () => console.log(`listening on :${port}`));
}

module.exports = app;

const assert = require('node:assert');
const app = require('./app');

const server = app.listen(0, async () => {
  const base = `http://localhost:${server.address().port}`;
  const post = (path, body, cookie) =>
    fetch(base + path, {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...(cookie && { cookie }) },
      body: JSON.stringify(body),
    });

  try {
    assert.equal((await post('/register', { username: 'alice', password: 'short' })).status, 400);
    assert.equal((await post('/register', { username: 'alice', password: 'correct horse' })).status, 201);
    assert.equal((await post('/register', { username: 'alice', password: 'correct horse' })).status, 409);

    assert.equal((await fetch(base + '/me')).status, 401);
    assert.equal((await post('/login', { username: 'alice' })).status, 400);

    // Successful login sets a session cookie that authenticates /me.
    const login = await post('/login', { username: 'alice', password: 'correct horse' });
    assert.equal(login.status, 200);
    const cookie = login.headers.get('set-cookie').split(';')[0];
    assert.deepEqual(await (await fetch(base + '/me', { headers: { cookie } })).json(), { username: 'alice' });

    // Logout kills the session server-side.
    assert.equal((await post('/logout', {}, cookie)).status, 204);
    assert.equal((await fetch(base + '/me', { headers: { cookie } })).status, 401);

    // Unknown user and wrong password look identical; 5 failures allowed, then locked out.
    assert.equal((await post('/login', { username: 'nobody', password: 'whatever1' })).status, 401);
    for (let i = 0; i < 4; i++) {
      assert.equal((await post('/login', { username: 'alice', password: 'wrong' })).status, 401);
    }
    const blocked = await post('/login', { username: 'alice', password: 'correct horse' });
    assert.equal(blocked.status, 429);
    assert.ok(Number(blocked.headers.get('retry-after')) > 0);

    console.log('ok');
  } finally {
    server.close();
  }
});

